class Solution{public:int largestIsland(vector<vector<int>>&g){int n=g.size(),id=2,ans=0;unordered_map<int,int>s;function<int(int,int)>f=[&](int i,int j){if(i<0||j<0||i==n||j==n||g[i][j]!=1)return 0;g[i][j]=id;return 1+f(i+1,j)+f(i-1,j)+f(i,j+1)+f(i,j-1);};for(int i=0;i<n;i++)for(int j=0;j<n;j++)if(g[i][j]==1){int z=f(i,j);s[id++]=z;ans=max(ans,z);}for(int i=0;i<n;i++)for(int j=0;j<n;j++)if(g[i][j]==0){unordered_set<int>x;int z=1;for(auto d:vector<pair<int,int>>{{1,0},{-1,0},{0,1},{0,-1}}){int u=i+d.first,v=j+d.second;if(u>=0&&v>=0&&u<n&&v<n&&g[u][v]>1&&x.insert(g[u][v]).second)z+=s[g[u][v]];}ans=max(ans,z);}return ans?ans:1;}};
